/**
 * Shape of public/content/structures.json (generated by
 * scripts/enrich-structures.mjs from Uberon, Wikidata and Wikimedia Commons).
 */
export interface GeneratedStructure {
  fma: string;
  definition?: string;
  description?: string;
  label?: string;
  synonyms?: string[];
  partOf?: string[];
  isA?: string[];
  wiki?: string;
  uberon?: string;
  wikidata?: string;
  image?: {
    src: string;
    page: string;
    artist: string;
    license: string;
  };
}

export const STRUCTURES_URL = "content/structures.json";

let cache: Promise<Record<string, GeneratedStructure>> | null = null;

/** Loads the reference file once and shares it between selections. */
export function loadStructures(): Promise<Record<string, GeneratedStructure>> {
  cache ??= fetch(STRUCTURES_URL)
    .then((r) => (r.ok ? r.json() : {}))
    .catch(() => ({}));
  return cache;
}
